# Assign a role (clerk, steward or viewer) to a user name on the sheet.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.settings.ValidateRole
  next: save
save:
  class: net.officefloor.hq.app.settings.SaveRole
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.settings.RespondWithSettings
# The sheet's settings (its clerk limit) and the roles set on it, re-read from the store.
load:
  class: net.officefloor.hq.app.settings.LoadSettings
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.settings.RespondWithSettings
package net.officefloor.hq.app.settings;

import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the role form: a user name (no spaces) and a role, clerk, steward or viewer. */
public class ValidateRole {
    private static final Set<String> ROLES = Set.of(SettingsRepository.CLERK, SettingsRepository.STEWARD, SettingsRepository.VIEWER);

    public void validate(@RequestBody RoleRequest request, Out<Role> role) throws BadRequestException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        String name = request == null || request.role() == null ? "" : request.role().trim();
        if (user.isEmpty()) {
            throw new BadRequestException("user is required");
        }
        if (user.chars().anyMatch(Character::isWhitespace)) {
            throw new BadRequestException("user must not contain spaces");
        }
        if (!ROLES.contains(name)) {
            throw new BadRequestException("role must be clerk, steward or viewer");
        }
        role.set(new Role(user, name));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveRole {
    public void save(@PathVariable("sheetId") String sheetId, @Val Role role, ServerHttpConnection connection,
            SettingsRepository repository, Audit audit, Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        repository.setRole(id, role.user(), role.role());
        audit.record("ROLE_SET sheet=" + id + " by=" + by + " user=" + role.user() + " role=" + role.role());
        settings.set(repository.load(id));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSettings {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository repository, AsOfView view, Out<Settings> settings) throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        settings.set(view.read(connection, id, () -> repository.load(id)));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSettings {
    public void respond(@Val Settings settings, ObjectResponse<Settings> response) {
        response.send(settings);
    }
}
package net.officefloor.hq.app.settings;

import java.util.List;

/** A sheet's settings: its clerk limit (two decimals; null means no limit), its floor (two decimals:
 *  the least a live due can be), its terms (the days after a claim's date that it is due by), its late percent (two decimals: what an
 *  overdue claim's due gains, of its figure, for every full 30 days it is overdue), the roles set on it, by user name. A name not listed is a clerk. And its policy date (yyyy-MM-dd; null when blank,
 *  meaning the sheet's today): a claim dated before it rounds half up, one on or after it half to even. And its period numbering from-date (yyyy-MM-dd; null when blank, meaning off):
 *  while set and the sheet's today is on or after it, a claim opened is numbered within its period. And each grade's own terms,
 *  by grade (a grade not listed uses the sheet's terms). And its cap (two decimals; null means none): a
 *  person's due-total is at most it. The clerk limit, floor, terms, late percent, grade terms and cap are those in
 *  force on the sheet's today; {@code dated} is every value recorded for each of them, by key (clerk-limit, floor,
 *  terms, terms-<grade>, late-pct, cap, proof-threshold), oldest from-date first. {@code permissions} is the permission
 *  matrix entries set, by action (open, settle, void, reassign, close, reopen), each a comma separated list of roles; an
 *  action not listed keeps the standing rule. {@code graceDays} is the days after a period's to-date it is left
 *  open (null when blank: off; not dated): changing the sheet's today closes each open period lapsed past them.
 *  {@code delegations} is each delegation of the steward role made on the sheet, oldest first.
 *  {@code entryDate} is the sheet's entry date (yyyy-MM-dd; null when blank: off; not dated): while set, it is the
 *  default date of a new claim instead of the sheet's today. */
public record Settings(String clerkLimit, String floor, int terms, String latePct, List<Role> roles, String policyDate,
        String periodNumberingFrom, java.util.Map<String, Integer> gradeTerms, String cap,
        java.util.Map<String, List<DatedValue>> dated, java.util.Map<String, String> permissions, Integer graceDays,
        List<Delegation> delegations, String entryDate) {
}
package net.officefloor.hq.app.settings;

public record RoleRequest(String user, String role) {
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse any change from a screen showing the sheet as of a date, any change by a viewer of the sheet, and any change at all to an archived sheet (400, nothing written). The first step of every endpoint
 *  that changes a sheet, except the bulk ones, where a viewer's selection is simply all refused. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        AsOfView.refuse(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        if (settings.role(id, by).equals(SettingsRepository.VIEWER)) {
            throw new BadRequestException("a viewer can change nothing");
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.settings.SettingsRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures (or tell of a change already recorded): never marked for a delegator. */
    private static final Set<String> REPORTS = Set.of("ROLLUP", "TOTALS", "SNAPSHOT", "ALERT", "NOTIFY");

    private final Path file;

    private final ObjectProvider<SettingsRepository> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingsRepository> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting
     *  under a delegation of the steward role (one covering the sheet's today) ends with for=<the steward
     *  who delegated>. */
    public synchronized void record(String entry) {
        entry = entry + delegatedFor(entry);
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** " for=<steward>" when the record (EVENT sheet=<id> by=<user> ...) is a change by a delegated user. */
    private String delegatedFor(String entry) {
        String[] parts = entry.split(" ", 4);
        if (parts.length < 3 || REPORTS.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
            return "";
        }
        String delegator = settings.getObject().delegator(parts[1].substring("sheet=".length()), parts[2].substring("by=".length()));
        return delegator == null ? "" : " for=" + delegator;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

/** A refused request: answered 400 with its message (escalation/…BadRequestException.yml). */
public class BadRequestException extends Exception {
    public BadRequestException(String message) {
        super(message);
    }
}

