        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
                (org.springframework.jdbc.core.RowCallbackHandler) rs -> perms.put(rs.getString("action"), rs.getString("roles")),
                sheetId);
